def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for regex matching.
    Supports literal characters, '.' (any character), '*' (zero or more of the preceding element),
    and '+' (one or more of the preceding element).
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = (i < len(text)) and (pattern[j] == text[i] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] in '*+':
            if pattern[j + 1] == '*':
                return (is_match(i, j + 2) or (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return first_match and (is_match(i + 1, j) or is_match(i + 1, j + 2))
        if first_match:
            return is_match(i + 1, j + 1)

        return False

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a dynamic programming approach for regex matching.
    Supports literal characters, '.' (any character), '*' (zero or more of the preceding element),
    and '+' (one or more of the preceding element).
    """

    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
        elif pattern[j - 1] == '+':
            dp[0][j] = False  # No match possible with a '+' at the start without preceding characters

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j - 1] == text[i - 1] or pattern[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (text[i - 1] == pattern[j - 2] or pattern[j - 2] == '.'))
            elif pattern[j - 1] == '+':
                dp[i][j] = dp[i - 1][j] and (text[i - 1] == pattern[j - 2] or pattern[j - 2] == '.')

    return dp[m][n]

def match(pattern: str, text: str) -> bool:
    """
    Implements a finite automaton based approach for regex matching.
    Supports literal characters, '.' (any character), '*' (zero or more of the preceding element),
    and '+' (one or more of the preceding element).
    """

    def build_finite_automaton(pattern: str):
        states = []
        state = {}

        for i in range(len(pattern) + 1):
            state[i] = {}
            states.append(state[i])

        for i in range(len(pattern)):
            char = pattern[i]
            if char == '*':
                for j in range(len(states)):
                    states[j][i] = states[j - 1].get(i - 1, False) if j > 0 else False  # From state j-1 or stay
            elif char == '+':
                for j in range(len(states)):
                    states[j][i] = states[j - 1].get(i - 1, False) if j > 0 else False
            else:
                for j in range(len(states)):
                    states[j][i] = (j > 0 and pattern[i - 1] == char) or (j > 0 and pattern[i - 1] == '.')

        return states

    states = build_finite_automaton(pattern)

    current_state = 0
    for char in text:
        next_state = len(states) - 1
        for i, state in enumerate(states):
            if char in state[current_state] or pattern[current_state] == '.' or pattern[current_state] == char:
                next_state = i
        current_state = next_state

    return current_state == len(states) - 1
